def zigzagLevelOrder(root):
    out = []
    def dfs(n, d):
        if not n:
            return
        if len(out) == d:
            out.append([])
        out[d].append(n.val)
        dfs(n.left, d + 1)
        dfs(n.right, d + 1)
    dfs(root, 0)
    return [row if i % 2 == 0 else row[::-1] for i, row in enumerate(out)]

